INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','modals-ability','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"modals-ability","title":"Ability, possibility and permission: can and could","level":"A2","order":25,"summary":"Use basic modals for ability and permission, and distinguish general past ability from a successful event.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["A modal keeps the next verb simple","Questions and negatives","General past ability","Permission and polite requests"],"rules":[{"title":"A modal keeps the next verb simple","explanation":"Can and could take a **base verb without to**. They do not take third-person -s. Can commonly describes present ability or informal permission. The surrounding context distinguishes those meanings.","pattern":"She **can swim**. / You **can leave** now.","commonMistakes":["She cans swim and she can to swim are not standard modal constructions."],"examples":["Express ability: “The assistant can **prepare** the visitor guide without help.”","Express ability: “The assistant can **restore** the old portrait without help.”"],"skill":"form"},{"title":"Questions and negatives","explanation":"Move the modal before the subject in a question. Put not after it for a negative. Cannot is normally written as one word; can’t is its common contraction. No do or does is needed.","pattern":"**Can** they help? / They **cannot help**.","commonMistakes":["Do they can help? adds an unnecessary auxiliary."],"examples":["Ask about ability: “**Can** she prepare the visitor guide?”","Ask about ability: “**Can** she restore the old portrait?”"],"skill":"meaning"},{"title":"General past ability","explanation":"Could can describe a general ability in the past. For one successful achievement on a particular occasion, affirmative was/were able to or managed to is often more natural. Could is still possible for perception and some mental processes.","pattern":"As a child, she **could swim**. / Yesterday, she **managed to escape**.","commonMistakes":["Could not can describe failure on one occasion; the restriction mainly concerns affirmative achievement."],"examples":["Use managed to for one successful event: “Yesterday, we managed to **prepare** the visitor guide despite the difficulty.”","Use managed to for one successful event: “Yesterday, we managed to **restore** the old portrait despite the difficulty.”"],"skill":"contrast"},{"title":"Permission and polite requests","explanation":"Can I asks permission; could I is often more tentative. Could you commonly makes a polite request, not a claim about past ability. Be able to supplies forms unavailable to can, such as will be able to.","pattern":"**Could you help** me? / I’ll **be able to come**.","commonMistakes":["Do not stack two central modals: will can is not standard. Use will be able to."],"examples":["Express future ability with able: “Next month, they will **be able to prepare** the visitor guide without help.”","Express future ability with able: “Next month, they will **be able to restore** the old portrait without help.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"a317e119-596e-5e9d-a00c-c0043ea03de1","topicSlug":"modals-ability","level":"A2","prompt":"Express ability: “The assistant can ____ the visitor guide without help.”","choices":[{"id":"A","text":"prepare"},{"id":"B","text":"prepares"},{"id":"C","text":"preparing"},{"id":"D","text":"to prepare"}],"answerId":"A","hint":"Ability is expressed by **can + base verb**.","explanation":"**Can** takes base **prepare**, even after a singular subject.","keywords":["present-ability"],"skill":"present-ability","contextKey":"modals-ability-1","fingerprint":"28990218e628a71ee94803bffe4efaaadfd73534fbd7b34e251e48923aa6f7ba","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Ability is expressed by **can + base verb**.","**Can** takes base **prepare**, even after a singular subject.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"**Can** takes base **prepare**, even after a singular subject.","B":"Central modals do not allow third-person -s on the following verb.","C":"Can alone does not take an -ing form.","D":"Can takes a bare infinitive, without to."}}},{"id":"b48ccdeb-9cff-52bd-aee2-5da83dc0ada7","topicSlug":"modals-ability","level":"A2","prompt":"Ask about ability: “____ she prepare the visitor guide?”","choices":[{"id":"A","text":"Cans"},{"id":"B","text":"Is can"},{"id":"C","text":"Can"},{"id":"D","text":"Does can"}],"answerId":"C","hint":"A modal forms its own question by moving before the subject.","explanation":"**Can** moves before she; no do is added.","keywords":["modal-question"],"skill":"modal-question","contextKey":"modals-ability-1","fingerprint":"51797354aed14fcc02d6e25c5d6575139b6ff8c394ea475c6c59beda36209f56","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A modal forms its own question by moving before the subject.","**Can** moves before she; no do is added.","Choose **Can**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Can does not take an -s ending.","B":"Be is not added before can.","C":"**Can** moves before she; no do is added.","D":"Do-support is not added to a can question."}}},{"id":"33b82d05-2ca4-5aa1-ada4-2613c2d32e0f","topicSlug":"modals-ability","level":"A2","prompt":"Use managed to for one successful event: “Yesterday, we managed to ____ the visitor guide despite the difficulty.”","choices":[{"id":"A","text":"preparing"},{"id":"B","text":"prepared"},{"id":"C","text":"prepare"},{"id":"D","text":"prepares"}],"answerId":"C","hint":"After **managed to**, the next verb returns to its base form.","explanation":"**Managed to prepare** describes successful completion on that occasion.","keywords":["past-achievement"],"skill":"past-achievement","contextKey":"modals-ability-1","fingerprint":"254a09c3e649383891f48ee2f93228233e0cb981515dd8af412dc2226cdf796e","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **managed to**, the next verb returns to its base form.","**Managed to prepare** describes successful completion on that occasion.","Choose **prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Managed in this meaning takes a to-infinitive, not to + -ing.","B":"The past marking is on managed, not on the infinitive.","C":"**Managed to prepare** describes successful completion on that occasion.","D":"The infinitive after to has no -s ending."}}},{"id":"dff495c3-8e7a-55e8-ac27-352c394d4b10","topicSlug":"modals-ability","level":"A2","prompt":"Express future ability with able: “Next month, they will ____ the visitor guide without help.”","choices":[{"id":"A","text":"be able prepare"},{"id":"B","text":"be able to prepare"},{"id":"C","text":"can prepare"},{"id":"D","text":"are able to prepare"}],"answerId":"B","hint":"Can has no infinitive form; use **be able to** after will.","explanation":"After **will**, use **be able to prepare**; this supplies future ability without stacking modals.","keywords":["future-ability"],"skill":"future-ability","contextKey":"modals-ability-1","fingerprint":"5af7b52ddaa232faee998f417c8b2ac98d7aeb41d4441566cb7c5f76ac198514","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Can has no infinitive form; use **be able to** after will.","After **will**, use **be able to prepare**; this supplies future ability without stacking modals.","Choose **be able to prepare**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Able requires to before the infinitive.","B":"After **will**, use **be able to prepare**; this supplies future ability without stacking modals.","C":"Will can combines two central modals, which standard English does not allow.","D":"After will, be must stay in its base form."}}},{"id":"5f99670c-f4c3-5575-af68-16be9d5a6b05","topicSlug":"modals-ability","level":"A2","prompt":"Express ability: “The assistant can ____ the old portrait without help.”","choices":[{"id":"A","text":"to restore"},{"id":"B","text":"restore"},{"id":"C","text":"restores"},{"id":"D","text":"restoring"}],"answerId":"B","hint":"Ability is expressed by **can + base verb**.","explanation":"**Can** takes base **restore**, even after a singular subject.","keywords":["present-ability"],"skill":"present-ability","contextKey":"modals-ability-2","fingerprint":"a0ec4e0255421eaf1a7ca24697f7dea68e30a932fed2bac8b437a95af54a5fbf","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Ability is expressed by **can + base verb**.","**Can** takes base **restore**, even after a singular subject.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Can takes a bare infinitive, without to.","B":"**Can** takes base **restore**, even after a singular subject.","C":"Central modals do not allow third-person -s on the following verb.","D":"Can alone does not take an -ing form."}}},{"id":"5f691274-6a5c-5e35-a5c1-63ad4f2578c9","topicSlug":"modals-ability","level":"A2","prompt":"Ask about ability: “____ she restore the old portrait?”","choices":[{"id":"A","text":"Is can"},{"id":"B","text":"Can"},{"id":"C","text":"Does can"},{"id":"D","text":"Cans"}],"answerId":"B","hint":"A modal forms its own question by moving before the subject.","explanation":"**Can** moves before she; no do is added.","keywords":["modal-question"],"skill":"modal-question","contextKey":"modals-ability-2","fingerprint":"97d603cea8aa35408424e3a3501a47cac363dec2d5068ff5876ac2ab1f5d0ca4","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A modal forms its own question by moving before the subject.","**Can** moves before she; no do is added.","Choose **Can**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Be is not added before can.","B":"**Can** moves before she; no do is added.","C":"Do-support is not added to a can question.","D":"Can does not take an -s ending."}}},{"id":"46fbd505-0046-556d-a941-add09174a505","topicSlug":"modals-ability","level":"A2","prompt":"Use managed to for one successful event: “Yesterday, we managed to ____ the old portrait despite the difficulty.”","choices":[{"id":"A","text":"restores"},{"id":"B","text":"restoring"},{"id":"C","text":"restored"},{"id":"D","text":"restore"}],"answerId":"D","hint":"After **managed to**, the next verb returns to its base form.","explanation":"**Managed to restore** describes successful completion on that occasion.","keywords":["past-achievement"],"skill":"past-achievement","contextKey":"modals-ability-2","fingerprint":"10145fd1d471e61b65845badd62a190e7d9f45428d5a616b958c7dd08be1bdca","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **managed to**, the next verb returns to its base form.","**Managed to restore** describes successful completion on that occasion.","Choose **restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"The infinitive after to has no -s ending.","B":"Managed in this meaning takes a to-infinitive, not to + -ing.","C":"The past marking is on managed, not on the infinitive.","D":"**Managed to restore** describes successful completion on that occasion."}}},{"id":"6817f555-605c-5dac-a12c-171957608192","topicSlug":"modals-ability","level":"A2","prompt":"Express future ability with able: “Next month, they will ____ the old portrait without help.”","choices":[{"id":"A","text":"are able to restore"},{"id":"B","text":"be able restore"},{"id":"C","text":"be able to restore"},{"id":"D","text":"can restore"}],"answerId":"C","hint":"Can has no infinitive form; use **be able to** after will.","explanation":"After **will**, use **be able to restore**; this supplies future ability without stacking modals.","keywords":["future-ability"],"skill":"future-ability","contextKey":"modals-ability-2","fingerprint":"5f70c587120e2b3185cb419e5c5f6088168c1d037128eb5e32f1828d3f181ea6","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Can has no infinitive form; use **be able to** after will.","After **will**, use **be able to restore**; this supplies future ability without stacking modals.","Choose **be able to restore**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"After will, be must stay in its base form.","B":"Able requires to before the infinitive.","C":"After **will**, use **be able to restore**; this supplies future ability without stacking modals.","D":"Will can combines two central modals, which standard English does not allow."}}},{"id":"79c1fad7-4201-592c-ae55-b389345aac9d","topicSlug":"modals-ability","level":"A2","prompt":"Express ability: “The assistant can ____ the garden fence without help.”","choices":[{"id":"A","text":"measures"},{"id":"B","text":"measuring"},{"id":"C","text":"to measure"},{"id":"D","text":"measure"}],"answerId":"D","hint":"Ability is expressed by **can + base verb**.","explanation":"**Can** takes base **measure**, even after a singular subject.","keywords":["present-ability"],"skill":"present-ability","contextKey":"modals-ability-3","fingerprint":"b843596749390cb98315d312838e7a6f70b9e8a7674d8d34d42f6c3e38d3be39","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Ability is expressed by **can + base verb**.","**Can** takes base **measure**, even after a singular subject.","Choose **measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Central modals do not allow third-person -s on the following verb.","B":"Can alone does not take an -ing form.","C":"Can takes a bare infinitive, without to.","D":"**Can** takes base **measure**, even after a singular subject."}}},{"id":"8b36e891-9aee-5256-a169-9684da99e47c","topicSlug":"modals-ability","level":"A2","prompt":"Ask about ability: “____ she measure the garden fence?”","choices":[{"id":"A","text":"Does can"},{"id":"B","text":"Cans"},{"id":"C","text":"Is can"},{"id":"D","text":"Can"}],"answerId":"D","hint":"A modal forms its own question by moving before the subject.","explanation":"**Can** moves before she; no do is added.","keywords":["modal-question"],"skill":"modal-question","contextKey":"modals-ability-3","fingerprint":"0867a89fc44bfb61cc435722260e403bcc31c74e7e898c705776cc9366472458","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["A modal forms its own question by moving before the subject.","**Can** moves before she; no do is added.","Choose **Can**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"Do-support is not added to a can question.","B":"Can does not take an -s ending.","C":"Be is not added before can.","D":"**Can** moves before she; no do is added."}}},{"id":"86bcc3a6-4c37-521c-aa89-3b4f2c4fb75f","topicSlug":"modals-ability","level":"A2","prompt":"Use managed to for one successful event: “Yesterday, we managed to ____ the garden fence despite the difficulty.”","choices":[{"id":"A","text":"measures"},{"id":"B","text":"measuring"},{"id":"C","text":"measured"},{"id":"D","text":"measure"}],"answerId":"D","hint":"After **managed to**, the next verb returns to its base form.","explanation":"**Managed to measure** describes successful completion on that occasion.","keywords":["past-achievement"],"skill":"past-achievement","contextKey":"modals-ability-3","fingerprint":"525a86e6cbdf1a4ecf8a988c36e98863d88fa7bf4c72750d08f419e529f5357b","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-past-ability"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["After **managed to**, the next verb returns to its base form.","**Managed to measure** describes successful completion on that occasion.","Choose **measure**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":